// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolen,
        bool payRoyalties
    ) public {
        // Admissible domain: feeRate <= 5_000, otherwise initialize reverts and property vacuously holds
        vm.assume(feeRate <= 5_000);

        c.initialize(
            baseToken,
            nft,
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            merkleRoot,
            useStolen,
            payRoyalties
        );

        // After initialize succeeds, the `initialized` flag MUST be true.
        assertTrue(c.initialized());
    }
}

